<?php namespace App; use Illuminate\Database\Eloquent\Model; class DentalReferral extends Model {protected $guarded=[];protected $dates=['referred_at','completed_at'];public function patient(){return $this->belongsTo(Patient::class);}public function complaint(){return $this->belongsTo(StudentComplaint::class,'student_complaint_id');}public function nurse(){return $this->belongsTo(User::class,'referring_nurse_id');}}
